style.css:
a[href="/home"] {
    background-image: url("https://i.imgur.com/B4DiCfe.png"); /* ✅ imagem direta extraída do seu link */
    background-size: contain;        /* mantém proporção sem cortar */
    background-repeat: no-repeat;
    background-position: center;
    color: transparent !important;   /* esconde o texto original */
    text-indent: -9999px;            /* empurra o texto pra fora da tela */
    display: inline-block;
    width: 110px;                    /* largura da logo */
    height: 40px;                    /* altura da logo */
    vertical-align: middle;
    transition: filter 0.25s ease-in-out;
}

a[href="/home"] span,
a[href="/home"] div {
    display: none !important;
}

a[href="/home"]:hover {
    filter: brightness(1.2);
}

header a[href="/home"] {
    margin-top: 2px;
}
